
'use strict';
const EN={back:'Back',close:'Close',name:'Your name',face:'Pick a face',shuffle:'More faces',create:'Create room',join:'Join room',joinCode:'Join with code',createTab:'Create',joinTab:'Join',roomCode:'Room code',nameHelp:'1–12 characters. A nickname is enough.',codeHelp:'Five characters from your host.',nameError:'Add a name, up to 12 characters.',codeError:'Enter the five-character code from your host.',codeInvalid:'Check the code. It uses letters and numbers, without I, O, 0 or 1.',qrPrefill:'Room {code} is ready to join.',title:'Blindstop',tagline:'Count in your head.<br><mark>Trust your timing.</mark>',closest:'Closest guess wins.',gameMeta:'2–8 players · 10 rounds · about 4 minutes',how:'How to play',how1:'Everyone gets the same target time.',how2:'Count silently. Tap when you think it is up.',how3:'The smallest average error wins.',players:'Players',of:'{n} of 8',you:'you',host:'host',start:'Start · 10 rounds',needPlayer:'Waiting for one more player',waitHost:'Waiting for {name} to start',invite:'Invite players',copyCode:'Copy code',copied:'Copied',copyFailed:'Select the text and copy it.',freeSeats:'{n} free seats',round:'Round {n} of 10',aim:'Your target',seconds:'seconds',begin:'Start counting when the screen turns dark.',stopAt:'Stop at',tap:'Tap',locked:'Locked in',waiting:'Waiting for {n} more',counting:'counting',tapped:'locked in',target:'Target {n} s',yourResult:'Your timing',early:'early',late:'late',exact:'right on time',missed:'No tap',penalty:'3.00 s penalty',closestName:'{name} was closest',tie:'Joint closest',nextRound:'Next round in {n}s',finalNext:'Final results in {n}s',reviewTime:'Preview paused · auto-advances in the game',average:'Average error',earned:'Points earned',final:'Final · 10 rounds',wins:'{name} wins',jointWins:'Joint winners',points:'{n} pts',plus:'＋{n}',averageValue:'{n} s average error',lobby:'Back to room',again:'Play again',evening:'Tonight',games:'{n} games played',oneGame:'1 game played',endEvening:'End the evening',eveningTotal:'Evening points',observation:'You went early in {n} of {total} rounds.',observationNeutral:'Your average error was {n} s across {total} rounds.',summary:'The evening, settled.',share:'Share the results',newRoom:'Start a new room',stillRoom:'Your room is still here',rejoin:'Rejoin room',somethingNew:'Start something new',gone:'Room not found',goneBody:'Check the code with your host. The room may have closed.',tryCode:'Try another code',backStart:'Back to start',full:'This room is full',fullBody:'All eight seats are taken. Ask the host to free a seat, then try again.',retry:'Try again',inGame:'A game is underway',inGameBody:'New players can join between games. Ask your host when this one ends.',offline:'No connection · reconnecting',offlineHelp:'Your tap is unavailable while reconnecting.',missedRound:'This round has ended',missedRoundBody:'You are still in the room. Join the next round.',connectionBack:'Connected again',newHost:'{name} is now the host',removeTitle:'Remove {name}?',removeBody:'They will leave this room. Their completed-game points stay in the evening total.',remove:'Remove player',cancel:'Cancel',leave:'Leave room',leaveTitle:'Leave this room?',leaveBody:'You can rejoin with the same browser while the room is open.',endTitle:'End the evening for everyone?',endBody:'Everyone gets the final table. This room will close.',confirmEnd:'End and show results',endGame:'End this game',endGameTitle:'End this game for everyone?',endGameBody:'The room stays open. This unfinished game adds no evening points.',roomMenu:'Room options',kicked:'You left the room',kickedBody:'The host removed you. You can start your own room.',unexpected:'The room could not load',unexpectedBody:'Try again. If the room is still open, you can return.',reload:'Try loading again',resultsHost:'Only the host can start the next game.',shareTitle:'Our Blindstop evening',shareIntro:'Blindstop · {n} games',shareLine:'{rank}. {name} — {points} pts',shareCopied:'Results copied. Paste them into your group chat.',qrCaption:'Scan to read the room code',inviteBody:'Read the code aloud, or show it to the people beside you.',atTarget:'on target',joined:'Room joined',savedTap:'Your timing is hidden until everyone finishes.',noTapWait:'No tap recorded',menu:'Options',resultUnits:'Error in seconds',removeLabel:'Remove {name}',selectFace:'Choose face {n}',recall:'Return to your evening',invalid:'Check the room code',game:'Blindstop',ready:'Ready when you are',hold:'Host actions',noGames:'No games completed yet.',summaryEmpty:'The room is closed.',shareEmpty:'Blindstop · no games completed',closed:'The evening has ended',closedBody:'This room is closed. Start a new room to play again.',pending:'A preview of the full room.',roundFinish:'Round complete'};
const t=(key,v={})=>(EN[key]??key).replace(/\{(\w+)\}/g,(_,k)=>String(v[k]??''));
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=(key,v)=>escapeHTML(t(key,v));
const svg=id=>`<svg aria-hidden="true"><use href="#${id}"/></svg>`;
const icons=id=>`<svg aria-hidden="true" viewBox="0 0 ${id==='sw'||id==='door'?'100 100':'24 24'}"><use href="#${id}"/></svg>`;
const colours=['tYel','tRed','tBlu','tPur','tGrn','tOrg','tPnk','tGry'];
let roster=['Artur','Mila','Tom','Ola','Kate','Noah','Alex','Lena'].map((name,i)=>({id:i,name,face:i+1,tile:colours[i],total:0,history:[]}));
let state={screen:'landing',count:5,me:0,host:0,code:'K7QMX',mode:'create',name:'Artur',face:1,facePage:0,round:1,target:7,elapsed:null,games:0,live:false,results:[],locked:false,started:0};
let tasks=[],countdownClock=null,toastTimer=null,formDraft={};
const app=document.getElementById('app'),dialog=document.getElementById('dialog');
const SCREENS=[
['landing','01 · Wejście','Wejście bez obietnic na wyrost','Usuwam „Seven seconds”, bo cel zmienia się co rundę. Zostają dwa konkretne działania i czas całej gry, nie tylko rundy. Nazwa Blindstop pozostaje robocza.'],
['create','02 · Utwórz pokój','Jedno zadanie na ekran','Wspólny formularz Create / Join zachowuje imię i twarz. Imię ma prawdziwą walidację. Cztery twarze nie udają całego katalogu.'],
['join','03 · Dołącz kodem','Kod da się wkleić','Jeden dostępny input zamiast pięciu osobnych pól. Pięć znaków zgodnie ze specyfikacją; wklejenie i automatyczna zamiana na wielkie litery.'],
['qrjoin','04 · Wejście z QR','Kod już jest, wpisz tylko imię','Osoba z linku zaproszenia nie powinna przepisywać kodu. To osobny stan tego samego formularza.'],
['lobbyHost','05 · Lobby gospodarza','Najpierw ludzie, potem start','Kod, zaproszenie, gracze i krótka instrukcja. Usunięcie gracza wymaga potwierdzenia. Start jest zablokowany, kiedy gospodarz jest sam.'],
['lobbyPlayer','06 · Lobby uczestnika','Wiadomo, na kogo czekasz','Uczestnik widzi gospodarza i te same zasady, ale nie ma przycisków sterujących cudzą rozgrywką.'],
['countdown','07 · Cel i odliczanie','Najpierw poznaj cel','Cel pojawia się przed startem, więc czytanie liczby nie zabiera czasu z rundy. Zmiana na ciemne pole to jednoznaczny moment rozpoczęcia liczenia.'],
['round','08 · Liczenie','Cały ekran jest przyciskiem','Żadnego zegara, animacji, listy ani komunikatu o innych. Rzeczywisty przycisk obsługuje dotyk i klawiaturę.'],
['waiting','09 · Zapisany ruch','Potwierdzenie bez zdradzania wyniku','Po tapnięciu widać potwierdzenie i osoby, które jeszcze liczą. Własny czas zostaje ukryty. Kolejne tapnięcie niczego nie zmienia.'],
['roundResult','10 · Wynik rundy','Trzy sekundy: znajdź swój wynik','Największy jest Twój błąd wraz ze słowem early / late. Zwycięzca pozostaje widoczny, a ranking daje kontekst. Automatyczne przejście zostaje.'],
['missed','11 · Brak tapnięcia','Brak ruchu nie oznacza spóźnienia','Kara jest podpisana, bez fałszywego znacznika +3.00 na osi czasu. Nie twierdzimy, że wiemy, kiedy gracz kliknął.'],
['gameResult','12 · Koniec gry: gospodarz','Wynik gry i punkty wieczoru','Średni błąd ma jednostkę, zdobyte punkty osobną kolumnę. Play again tylko u gospodarza. Przejście do lobby nie kasuje tabeli wieczoru.'],
['gameResultPlayer','13 · Koniec gry: uczestnik','Wynik bez fałszywej kontroli','Uczestnik wraca do pokoju. Nie może sam uruchomić rewanżu dla wszystkich.'],
['lobbyTotals','14 · Lobby po grze','Ten sam pokój, rośnie wynik','Kod i twarze pozostają te same. Pojawia się tabela wieczoru i jawna akcja zakończenia. Bez przedwczesnego wyboru gier.'],
['summary','15 · Podsumowanie wieczoru','Wynik do wysłania znajomym','Nowy ekran: zwycięzca, liczba gier, tabela, własna obserwacja i systemowe udostępnianie tekstu. Zastępuje sprzeczny komunikat „Scores are not saved”.'],
['return','16 · Powrót','Najważniejsza jest kontynuacja','Powrót do istniejącego pokoju jest główną akcją. Rozpoczęcie nowego wieczoru pozostaje drugorzędne.'],
['gone','17 · Nie znaleziono pokoju','Najpierw pozwól poprawić kod','Nie mówimy, że pokoje znikają od razu po wyjściu ostatniej osoby. To nie zgadzało się z regułą czasu życia.'],
['full','18 · Pokój pełny','Odmowa ma konkretny powód','Pełny pokój nie jest pokojem usuniętym. Zachowujemy dane i pozwalamy spróbować ponownie.'],
['inGame','19 · Gra już trwa','Nowy gracz czeka do lobby','Ten stan dotyczy nowej osoby. Powracająca osoba zachowuje prawo do dołączenia w trakcie gry.'],
['offline','20 · Zerwane połączenie','Wyłączona akcja, nie tylko kolor','Pole tapnięcia naprawdę jest disabled. Nakładka nie resetuje pokoju; w aplikacji powrót wymaga aktualnego stanu serwera.'],
['reconnected','21 · Powrót po rundzie','Nie wracaj do starego timera','Po dłuższej przerwie pokazujemy, że runda minęła. Nie odtwarzamy starego odliczania ani nie zgadujemy wyniku.'],
['hostChanged','22 · Nowy gospodarz','Krótki komunikat, gra trwa','Nowy gospodarz jest nazwany wprost. Rola i przyciski zmieniają się razem.'],
['kicked','23 · Usunięty uczestnik','Osobna przyczyna wyjścia','Komunikat po usunięciu nie sugeruje awarii aplikacji ani zamknięcia całego pokoju.'],
['unexpected','24 · Błąd odczytu','Jedna droga powrotu','Osobny stan błędu z ponowieniem. Dane formularza nie powinny znikać.']
];
function people(){return roster.filter(p=>p.active!==false).slice(0,state.count)}
function eveningPeople(){return roster.filter(p=>p.total>0||people().includes(p))}
function me(){return roster[state.me]}
function avatar(p,cls=''){return `<span class="avatar ${cls}" style="background:var(--${p.tile})"><svg viewBox="90 90 900 900" aria-hidden="true"><use href="#face${p.face}"/></svg></span>`}
function btn(key,act,cls='primary',args=''){return `<button class="${cls}" data-action="${act}" ${args}>${e(key)}</button>`}
function header(label='',menu=false){return `<header class="screen-header"><span>${escapeHTML(state.code)}</span><span>${label}</span>${menu?`<button class="menu" data-action="menu" aria-label="${e('roomMenu')}">···</button>`:''}</header>`}
function roundHeader(){return header(e('round',{n:state.round}))}
function clearTimers(){tasks.forEach(clearTimeout);tasks=[];if(countdownClock)clearInterval(countdownClock);countdownClock=null}
function later(fn,ms){tasks.push(setTimeout(fn,ms))}
function note(){const idx=SCREENS.findIndex(x=>x[0]===state.screen),s=SCREENS[Math.max(0,idx)];document.getElementById('screen-picker').value=s[0];document.getElementById('notes').innerHTML=`<p class="eyebrow">DLACZEGO TAK</p><div class="number">${String(Math.max(0,idx)+1).padStart(2,'0')}</div><h3>${s[2]}</h3><p>${s[3]}</p><details><summary>Co sprawdzić w tej wersji</summary><ol><li>Utwórz pokój, wpisz imię i wybierz twarz.</li><li>Uruchom demo: cel → odliczanie → tapnięcie → wynik.</li><li>Sprawdź 8 graczy i osobny widok uczestnika.</li><li>Po grze wróć do pokoju, zakończ wieczór i udostępnij wynik.</li></ol><p>To propozycja UX, nie nowa specyfikacja. Tekst aplikacji pozostaje angielski. Panel po polsku służy wyłącznie do oceny mockupu.</p></details>`}
function navigate(screen,{live=false,seed=false}={}){clearTimers();if(dialog.open)dialog.close();state.live=live;state.screen=screen;state.locked=false;if(seed)seedScreen(screen);render();note();if(live&&screen==='countdown')runCountdown();if(live&&screen==='round')startRound();app.scrollTop=0;}
function seedScreen(screen){roster.forEach(p=>p.active=true);state.round=4;state.target=7;state.elapsed=6.79;state.results=people().map((p,i)=>({id:p.id,error:[-.21,.04,.88,-.11,-1.4,.32,-.51,.63][i]}));if(['gameResult','gameResultPlayer','lobbyTotals','summary'].includes(screen)){state.games=1;people().forEach((p,i)=>{p.history=Array.from({length:10},(_,j)=>({error:[.34,.19,.61,.28,.97,.45,.52,.76][i]*(j%3===0?-1:1)}));});assignPreviewTotals();}else if(!['return'].includes(screen)){state.games=0;roster.forEach(p=>{p.total=0;p.history=[]})}state.me=['lobbyPlayer','gameResultPlayer'].includes(screen)?1:0;state.host=screen==='hostChanged'?state.me:0;if(screen==='missed')state.results.find(x=>x.id===state.me).error=null;if(screen==='create')state.mode='create';if(['join','qrjoin'].includes(screen))state.mode='join';if(screen==='qrjoin')formDraft.code=state.code;}
function mean(p){return p.history.length?p.history.reduce((s,r)=>s+(r.error===null?3:Math.abs(r.error)),0)/p.history.length:0}
function sortedFinal(){return [...people()].sort((a,b)=>mean(a)-mean(b)||a.id-b.id)}
function placement(p){const n=people().length;return n-people().filter(x=>mean(x)<mean(p)-1e-9).length}
function assignPreviewTotals(){people().forEach(p=>p.total=placement(p))}
function observation(){const p=me(),valid=p.history.filter(r=>r.error!==null),early=valid.filter(r=>r.error<0).length;return early>valid.length/2?e('observation',{n:early,total:p.history.length}):e('observationNeutral',{n:mean(p).toFixed(2),total:p.history.length||10})}
function playerRows({totals=false,host=false,waiting=false}={}){return `<div class="list">${people().map(p=>`<div class="row ${p.id===state.me?'self':''}">${avatar(p)}<div class="name"><strong>${escapeHTML(p.name)}</strong>${p.id===state.me?` <small>${e('you')}</small>`:''}${p.id===state.host?`<div class="subline">${e('host')}</div>`:''}</div>${totals?`<div class="right">${p.total}<span class="sr-only"> ${e('points',{n:''})}</span></div>`:''}${waiting?`<div class="right">${p.id===state.me||p.id%2===1?`<span aria-label="${e('tapped')}">${icons('t')}</span>`:`<small class="muted">${e('counting')}</small>`}</div>`:host&&p.id!==state.me?`<button class="remove" data-action="remove" data-id="${p.id}" aria-label="${e('removeLabel',{name:p.name})}">${icons('x')}</button>`:''}</div>`).join('')}</div>`}
function landing(recall=false){return `<div class="screen-header"><span>${e('game')}</span></div><div class="intro">${icons('sw').replace('<svg ','<svg class="watch" ')}<h1>${e('title')}</h1><p>${t('tagline')}</p><p class="muted">${e('closest')}</p></div><div class="grow"></div>${recall?`<div class="room-recall"><p class="meta">${e('stillRoom')}</p><p class="room-code">${escapeHTML(state.code)}</p></div><div class="bottom">${btn('rejoin','rejoin')}${btn('somethingNew','new','secondary')}</div>`:`<div class="bottom">${btn('create','create')}${btn('joinCode','join','secondary')}<p class="meta center">${e('gameMeta')}</p></div>`}`}
function form(){const join=state.mode==='join',qr=state.screen==='qrjoin';return `<header class="screen-header"><button data-action="home">${e('back')}</button><span>${e('game')}</span></header><div role="tablist" class="tabs"><button type="button" role="tab" aria-selected="${!join}" data-action="create">${e('createTab')}</button><button type="button" role="tab" aria-selected="${join}" data-action="join">${e('joinTab')}</button></div><h2>${e(join?'join':'create')}</h2><form id="join-form" novalidate style="display:contents">${join?(qr?`<div class="notice">${e('qrPrefill',{code:state.code})}</div><input name="code" type="hidden" value="${state.code}">`:`<div class="field"><label for="room-code">${e('roomCode')}</label><input class="code" id="room-code" name="code" maxlength="5" autocomplete="off" autocapitalize="characters" spellcheck="false" value="${escapeHTML(formDraft.code||'')}" placeholder="K7QMX" aria-describedby="code-help"><p class="help" id="code-help">${e('codeHelp')}</p></div>`):''}<div class="field"><label for="your-name">${e('name')}</label><input id="your-name" name="name" maxlength="12" autocomplete="nickname" value="${escapeHTML(state.name)}" aria-describedby="name-help"><p class="help" id="name-help">${e('nameHelp')}</p><p id="form-error" class="error" role="alert" hidden></p></div><div><div class="split"><span class="small">${e('face')}</span><button type="button" class="text-button" data-action="shuffle">${e('shuffle')}</button></div><div class="faces">${Array.from({length:4},(_,i)=>{const f=i+1+state.facePage*4;return `<button type="button" class="face-button ${state.face===f?'selected':''}" style="background:var(--${colours[state.me]})" data-action="face" data-id="${f}" aria-pressed="${state.face===f}" aria-label="${e('selectFace',{n:f})}"><svg viewBox="90 90 900 900" aria-hidden="true"><use href="#face${f}"/></svg></button>`}).join('')}</div></div><div class="bottom"><button class="primary" type="submit">${e(join?'join':'create')}</button></div></form>`}
function lobby(){const host=state.me===state.host,totals=state.games>0;return `${state.screen==='hostChanged'?`<div class="notice" role="status">${e('newHost',{name:me().name})}</div>`:''}${header(e('ready'),true)}<div><p class="meta">${e('roomCode')}</p><div class="split"><span class="room-code">${state.code}</span><button class="text-button" data-action="invite">${e('invite')}</button></div></div><div><div class="split meta" style="margin-bottom:8px"><span>${e(totals?'eveningTotal':'players')}</span><span>${e('of',{n:state.count})}</span></div>${playerRows({totals,host})}${state.count<8?`<p class="help">${e('freeSeats',{n:8-state.count})}</p>`:''}</div><div class="game-label rule">${icons('sw')}<div><h3>${e('game')}</h3><p class="meta">${e('gameMeta')}</p></div></div>${!totals?`<p class="meta">${e('how2')} ${e('how3')}</p>`:''}<div class="bottom">${host?btn(state.count<2?'needPlayer':'start','start','primary',state.count<2?'disabled':''):`<p class="status">${e('waitHost',{name:roster[state.host].name})}</p>`}${host&&totals?btn('endEvening','endEvening','text-button'):''}</div>`}
function countdown(){return `${roundHeader()}<div class="countdown"><div><p class="meta">${e('aim')}</p><p class="target-preview">${state.target.toFixed(2)} <small>s</small></p></div><div class="count-ring"><svg viewBox="0 0 200 200" aria-hidden="true"><use href="#ring"/></svg><span class="count-digit" id="count-digit">3</span></div><p class="muted">${e('begin')}</p></div>`}
function round(){const off=state.screen==='offline';return `${off?`<div class="banner" role="status">${e('offline')}</div>`:''}${roundHeader()}<button class="tap-zone" id="tap-zone" data-action="tap" ${off?'disabled':''} aria-label="${e('stopAt')} ${state.target.toFixed(2)} ${e('seconds')}. ${e('tap')}"><span class="meta">${e('stopAt')}</span><span class="target">${state.target.toFixed(2)}</span><span class="tap-label">${e('tap')}</span></button>${off?`<p class="meta center">${e('offlineHelp')}</p>`:''}`}
function waiting(){return `${roundHeader()}<div class="locked">${icons('t')}<h2>${e(state.elapsed===null?'noTapWait':'locked')}</h2><p class="muted">${e('waiting',{n:Math.max(1,Math.floor(state.count/2))})}</p></div>${playerRows({waiting:true})}<div class="grow"></div><p class="meta center">${e('savedTap')}</p>`}
function errorLabel(error){return error===null?e('penalty'):error===0?e('exact'):`${Math.abs(error).toFixed(2)} s ${e(error<0?'early':'late')}`}
function roundResult(){const own=state.results.find(r=>r.id===state.me)||{error:-.21};const sorted=[...state.results].sort((a,b)=>(a.error===null?3:Math.abs(a.error))-(b.error===null?3:Math.abs(b.error)));const first=sorted[0];const best=first?roster[first.id]:me();const next=state.round===10?'finalNext':'nextRound';return `${roundHeader()}<div class="result-personal"><p class="meta">${e('yourResult')}</p><div class="result-number">${own.error===null?e('missed'):Math.abs(own.error).toFixed(2)+' <small>s '+e(own.error===0?'atTarget':own.error<0?'early':'late')+'</small>'}</div><p class="meta">${own.error===null?e('penalty')+' · ':''}${e('target',{n:state.target.toFixed(2)})}</p></div><div class="split rule"><div class="game-label">${avatar(best,'small')}<span class="small">${e('closestName',{name:best.name})}</span></div><span class="small">${first&&first.error!==null?Math.abs(first.error).toFixed(2)+' s':''}</span></div><div><div class="split meta"><span>${e('early')}</span><span>${e('late')}</span></div>${sorted.map(r=>{const p=roster[r.id],w=r.error===null?0:Math.min(Math.abs(r.error)/1.5*50,50);return `<div class="error-row"><div class="split"><span class="who">${avatar(p,'small')}<span>${p.id===state.me?'<mark>':''}${escapeHTML(p.name)}${p.id===state.me?'</mark>':''}</span></span><span>${r.error===null?e('missed'):(r.error<0?'−':'+')+Math.abs(r.error).toFixed(2)+' s'}</span></div>${r.error===null?`<p class="meta" style="margin-left:34px">${e('penalty')}</p>`:`<div class="track" aria-hidden="true"><span style="width:${w}%;left:${r.error<0?50-w:50}%"></span></div>`}</div>`}).join('')}</div><div class="bottom center"><div class="auto-track"><div id="auto-progress" style="width:100%"></div></div><p class="meta" id="auto-label">${e(state.live?next:'reviewTime',{n:3})}</p></div>`}
function gameResult(){const sorted=sortedFinal(),winner=sorted[0];return `${header(e('final'))}<div class="winner">${avatar(winner,'large')}<div><h2>${e('wins',{name:winner.name})}</h2><p class="meta">${e('averageValue',{n:mean(winner).toFixed(2)})}</p></div></div><div><div class="split meta" style="margin-bottom:8px"><span>${e('average')}</span><span>${e('earned')}</span></div><div class="list">${sorted.map((p,i)=>`<div class="row ${p.id===state.me?'self':''}"><span class="rank">${1+sorted.filter(x=>mean(x)<mean(p)-1e-9).length}</span>${avatar(p)}<div class="name"><strong>${escapeHTML(p.name)}</strong>${p.id===state.me?' <small>'+e('you')+'</small>':''}<div class="subline">${mean(p).toFixed(2)} s</div></div><div class="right">${e('plus',{n:placement(p)})}</div></div>`).join('')}</div></div><p class="observation">${observation()}</p><div class="bottom">${state.me===state.host?btn('again','again'):''}${btn('lobby','lobby',state.me===state.host?'secondary':'primary')}${state.me!==state.host?`<p class="meta center">${e('resultsHost')}</p>`:''}</div>`}
function summary(){const sorted=[...eveningPeople()].sort((a,b)=>b.total-a.total||a.id-b.id),winner=sorted[0];return `${header(e('evening'))}<p class="meta">${e('summary')}</p><div class="winner">${avatar(winner,'large')}<div><h2>${state.games?e('wins',{name:winner.name}):e('summaryEmpty')}</h2><p class="meta">${e(state.games===1?'oneGame':'games',{n:state.games})}</p></div></div><div class="list">${sorted.map(p=>`<div class="row ${p.id===state.me?'self':''}"><span class="rank">${1+sorted.filter(x=>x.total>p.total).length}</span>${avatar(p)}<span class="name"><strong>${escapeHTML(p.name)}</strong></span><span class="right">${e('points',{n:p.total})}</span></div>`).join('')}</div>${state.games?`<p class="observation">${observation()}</p>`:`<p class="muted">${e('noGames')}</p>`}<div class="bottom">${btn('share','share')}${btn('newRoom','new','secondary')}</div>`}
function edge(){const configs={gone:['gone','goneBody','tryCode','join'],full:['full','fullBody','retry','retryJoin'],inGame:['inGame','inGameBody','retry','retryJoin'],kicked:['kicked','kickedBody','newRoom','new'],unexpected:['unexpected','unexpectedBody','reload','rejoin'],reconnected:['missedRound','missedRoundBody','lobby','lobby']};const c=configs[state.screen]||configs.gone;return `${header('')}<div class="grow"></div><div class="center">${icons('door').replace('<svg ','<svg style="width:90px;height:90px;margin:0 auto 24px" ')}<h2>${e(c[0])}</h2><p class="muted" style="margin-top:14px">${e(c[1])}</p></div><div class="grow"></div><div class="bottom">${btn(c[2],c[3])}${state.screen!=='kicked'?btn('backStart','home','text-button'):''}</div>`}
function render(){app.className='screen'+(state.count===8?' compact':'');const s=state.screen;app.innerHTML=s==='landing'?landing():s==='return'?landing(true):['create','join','qrjoin'].includes(s)?form():['lobbyHost','lobbyPlayer','lobbyTotals','hostChanged'].includes(s)?lobby():s==='countdown'?countdown():['round','offline'].includes(s)?round():s==='waiting'?waiting():['roundResult','missed'].includes(s)?roundResult():['gameResult','gameResultPlayer'].includes(s)?gameResult():s==='summary'?summary():edge();app.querySelectorAll('.right svg').forEach(el=>{el.style.width='22px';el.style.height='22px'});}
function rememberForm(){const n=document.getElementById('your-name');if(n)state.name=n.value;const c=document.getElementById('room-code');if(c)formDraft.code=c.value;}
function beginGame(){clearTimers();roster.forEach(p=>p.history=[]);state.round=1;state.target=7;state.elapsed=null;navigate('countdown',{live:true})}
function runCountdown(){let n=3;countdownClock=setInterval(()=>{n--;if(n===0){navigate('round',{live:true})}else{const d=document.getElementById('count-digit');if(d)d.textContent=n}},1000)}
function startRound(){state.started=performance.now();state.elapsed=null;state.locked=false;later(()=>finishTap(null),(state.target+8)*1000)}
function finishTap(elapsed){if(state.locked)return;state.locked=true;clearTimers();state.elapsed=elapsed;state.results=people().map((p,i)=>({id:p.id,error:p.id===state.me?(elapsed===null?null:elapsed-state.target):((Math.sin(state.round*7.1+i*3.7)*.82)+(i%3)*.13)}));people().forEach(p=>p.history.push({error:state.results.find(x=>x.id===p.id).error}));state.screen='waiting';render();note();later(()=>{state.screen='roundResult';render();note();let remaining=3;countdownClock=setInterval(()=>{remaining--;const l=document.getElementById('auto-label'),bar=document.getElementById('auto-progress');if(l)l.textContent=t(state.round===10?'finalNext':'nextRound',{n:remaining});if(bar)bar.style.width=(remaining/3*100)+'%';if(remaining===0){clearTimers();if(state.round===10){people().forEach(p=>p.total+=placement(p));state.games++;navigate('gameResult')}else{state.round++;state.target=[7,4.5,9.25,6,11,3.75,8.5,5.25,10,7.75][state.round-1];navigate('countdown',{live:true})}}},1000)},1000)}
function toast(msg){clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=msg;el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,3000)}
function openDialog(title,body,actions){dialog.innerHTML=`<button class="dialog-close" data-action="dismiss" aria-label="${e('close')}">${icons('x')}</button><h2>${title}</h2>${body}<div class="bottom">${actions}</div>`;dialog.showModal()}
async function copyText(text){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);return true}const a=document.createElement('textarea');a.value=text;dialog.open?dialog.append(a):document.body.append(a);a.select();const ok=document.execCommand('copy');a.remove();return ok}catch{return false}}
async function share(){const sorted=[...eveningPeople()].sort((a,b)=>b.total-a.total);const text=[t('shareIntro',{n:state.games}),...sorted.map(p=>t('shareLine',{rank:1+sorted.filter(x=>x.total>p.total).length,name:p.name,points:p.total}))].join('\n');try{if(navigator.share){await navigator.share({title:t('shareTitle'),text});return}}catch(err){if(err.name==='AbortError')return}const ok=await copyText(text);toast(t(ok?'shareCopied':'copyFailed'));if(!ok)openDialog(e('share'),`<textarea style="width:100%;min-height:180px" readonly>${escapeHTML(text)}</textarea>`,btn('close','dismiss','secondary'))}
function invite(){openDialog(e('invite'),`<p>${e('inviteBody')}</p><img class="qr" src="data:image/png;base64," alt="${e('roomCode')} ${state.code}"><div class="center room-code">${state.code}</div><p class="meta center">${e('qrCaption')}</p>`,btn('copyCode','copy')+btn('close','dismiss','secondary'));toast('QR w prototypie zawiera sam kod, nie zaproszenie do serwera.')}
async function action(a,el){rememberForm();switch(a){case 'home':navigate('landing');break;case 'create':state.mode='create';navigate('create');break;case 'join':state.mode='join';navigate('join');break;case 'new':state.games=0;roster.forEach(p=>{p.total=0;p.history=[];p.active=true});state.me=0;state.host=0;state.mode='create';navigate('create');break;case 'shuffle':state.facePage=1-state.facePage;state.face=state.facePage*4+1;render();break;case 'face':state.face=Number(el.dataset.id);render();break;case 'start':case 'again':if(state.me===state.host&&state.count>=2)beginGame();break;case 'tap':if(state.live)finishTap((performance.now()-state.started)/1000);else{state.elapsed=6.79;navigate('waiting')}break;case 'lobby':navigate(state.me===state.host?(state.games?'lobbyTotals':'lobbyHost'):'lobbyPlayer');break;case 'rejoin':navigate(state.me===state.host?'lobbyHost':'lobbyPlayer');break;case 'retryJoin':state.mode='join';navigate('join');break;case 'invite':invite();break;case 'copy':toast(t(await copyText(state.code)?'copied':'copyFailed'));break;case 'dismiss':dialog.close();break;case 'share':await share();break;case 'endEvening':openDialog(e('endTitle'),`<p>${e('endBody')}</p>`,btn('confirmEnd','confirmEnd')+btn('cancel','dismiss','secondary'));break;case 'confirmEnd':navigate('summary');break;case 'remove':{const p=roster[Number(el.dataset.id)];openDialog(e('removeTitle',{name:p.name}),`<p>${e('removeBody')}</p>`,btn('remove','confirmRemove','primary',`data-id="${p.id}"`)+btn('cancel','dismiss','secondary'));break}case 'confirmRemove':{const id=Number(el.dataset.id);roster[id].active=false;state.count--;dialog.close();render();break}case 'menu':openDialog(e('roomMenu'),'',(state.me===state.host?btn('endEvening','endEvening','secondary'):'')+btn('leave','leave','secondary')+btn('cancel','dismiss','text-button'));break;case 'leave':openDialog(e('leaveTitle'),`<p>${e('leaveBody')}</p>`,btn('leave','confirmLeave')+btn('cancel','dismiss','secondary'));break;case 'confirmLeave':navigate('return');break;}}
app.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(b&&!b.disabled)action(b.dataset.action,b)});dialog.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(b)action(b.dataset.action,b)});
app.addEventListener('input',ev=>{if(ev.target.name==='code')ev.target.value=ev.target.value.toUpperCase().replace(/\s/g,'')});
app.addEventListener('submit',ev=>{ev.preventDefault();rememberForm();const fd=new FormData(ev.target),name=String(fd.get('name')||'').trim(),code=String(fd.get('code')||'').trim().toUpperCase();let error='';if(!name||name.length>12)error='nameError';else if(state.mode==='join'&&code.length!==5)error='codeError';else if(state.mode==='join'&&!/^[ABCDEFGHJKLMNPQRSTUVWXYZ23456789]{5}$/.test(code))error='codeInvalid';if(error){const box=document.getElementById('form-error');box.textContent=t(error);box.hidden=false;document.getElementById(error==='nameError'?'your-name':'room-code')?.focus();return}state.name=name;state.me=state.mode==='create'?0:1;state.host=0;roster[state.me].name=name;roster[state.me].face=state.face;if(state.mode==='join'&&code!=='K7QMX'){navigate('gone');return}state.code='K7QMX';navigate(state.mode==='create'?'lobbyHost':'lobbyPlayer');});
const picker=document.getElementById('screen-picker');picker.innerHTML=SCREENS.map(s=>`<option value="${s[0]}">${s[1]}</option>`).join('');picker.addEventListener('change',()=>navigate(picker.value,{seed:true}));document.getElementById('prev').onclick=()=>navigate(SCREENS[(SCREENS.findIndex(s=>s[0]===state.screen)+SCREENS.length-1)%SCREENS.length][0],{seed:true});document.getElementById('next').onclick=()=>navigate(SCREENS[(SCREENS.findIndex(s=>s[0]===state.screen)+1)%SCREENS.length][0],{seed:true});document.getElementById('play-demo').onclick=()=>{state.me=0;state.host=0;beginGame()};document.getElementById('reset-demo').onclick=()=>{location.hash='';location.reload()};document.getElementById('player-count').onchange=ev=>{state.count=Math.min(Number(ev.target.value),roster.length);navigate(state.screen,{seed:true})};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.live){clearTimers();state.live=false;state.screen='reconnected';render();note()}});
window.addEventListener('pagehide',clearTimers);const hash=new URLSearchParams(location.hash.slice(1));if(hash.get('join')){state.mode='join';formDraft.code='K7QMX';navigate('qrjoin')}else navigate('landing');
